// Device-specific step illustrations, drawn as inline SVG (no photos, no copyrighted artwork).
// Every scene is language-neutral: only numbered callouts; the legend text lives in the JSON content.
// Usage: illustrate(sceneId, {accent, device}, altText) -> SVG string.
const INK = '#1f2937', SKIN = '#f6d3b5', SKIN2 = '#e8b994', AIR = '#2563eb', OK = '#15803d', BAD = '#b91c1c', METAL = '#b8c2cc', PAPER = '#ffffff';
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const SK = (extra, w = 3) => (/\bstroke="/.test(extra) ? '' : `stroke="${INK}" `) + (/\bstroke-width=/.test(extra) ? '' : `stroke-width="${w}" `);
const R = (x, y, w, h, f, rx = 6, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" ${SK(extra)}${extra}/>`;
const C = (x, y, r, f, extra = '') => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" ${SK(extra)}${extra}/>`;
const P = (d, f = 'none', w = 3, extra = '') => `<path d="${d}" fill="${f}" ${SK(extra, w)}stroke-linejoin="round" stroke-linecap="round" ${extra}/>`;
const T = (x, y, s, size = 18, f = INK, w = 700) => `<text x="${x}" y="${y}" font-size="${size}" font-weight="${w}" fill="${f}" text-anchor="middle" font-family="system-ui,sans-serif">${esc(s)}</text>`;
const G = (inner, tx = 0, ty = 0, rot = 0, sc = 1) => `<g transform="translate(${tx} ${ty}) rotate(${rot}) scale(${sc})">${inner}</g>`;
function arrow(x1, y1, x2, y2, col = AIR, w = 4) {
  const a = Math.atan2(y2 - y1, x2 - x1), h = 11;
  const p1 = [x2 - h * Math.cos(a - 0.45), y2 - h * Math.sin(a - 0.45)], p2 = [x2 - h * Math.cos(a + 0.45), y2 - h * Math.sin(a + 0.45)];
  return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/><polygon points="${x2},${y2} ${p1[0].toFixed(1)},${p1[1].toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}" fill="${col}"/>`;
}
function curve(x1, y1, cx, cy, x2, y2, col = AIR, w = 4) {
  const a = Math.atan2(y2 - cy, x2 - cx), h = 11;
  const p1 = [x2 - h * Math.cos(a - 0.45), y2 - h * Math.sin(a - 0.45)], p2 = [x2 - h * Math.cos(a + 0.45), y2 - h * Math.sin(a + 0.45)];
  return `<path d="M${x1} ${y1} Q${cx} ${cy} ${x2} ${y2}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/><polygon points="${x2},${y2} ${p1[0].toFixed(1)},${p1[1].toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}" fill="${col}"/>`;
}
// wavy breath lines; dir: 'out' (away from mouth to +x) or 'in' (toward mouth)
function breath(x, y, dir = 'out', len = 60, col = AIR, n = 3) {
  let s = '';
  for (let i = 0; i < n; i++) {
    const yy = y + (i - (n - 1) / 2) * 14;
    if (dir === 'out') s += `<path d="M${x} ${yy} q${len / 4} -8 ${len / 2} 0 t${len / 2} 0" fill="none" stroke="${col}" stroke-width="3.5" stroke-linecap="round" stroke-dasharray="2 7"/>` + arrow(x + len - 6, yy, x + len + 6, yy, col, 3);
    else s += `<path d="M${x + len} ${yy} q${-len / 4} -8 ${-len / 2} 0 t${-len / 2} 0" fill="none" stroke="${col}" stroke-width="3.5" stroke-linecap="round" stroke-dasharray="2 7"/>` + arrow(x + 6, yy, x - 6, yy, col, 3);
  }
  return s;
}
const num = (n, x, y) => `<g class="callout"><circle cx="${x}" cy="${y}" r="13" fill="#fde047" stroke="${INK}" stroke-width="2.5"/><text x="${x}" y="${y + 6}" font-size="16" font-weight="800" text-anchor="middle" fill="${INK}" font-family="system-ui,sans-serif">${String.fromCharCode(64 + n)}</text></g>`;
const ok = (x, y) => `<g><circle cx="${x}" cy="${y}" r="17" fill="${OK}"/><path d="M${x - 8} ${y} l6 7 l11 -13" fill="none" stroke="#fff" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/></g>`;
const no = (x, y) => `<g><circle cx="${x}" cy="${y}" r="17" fill="${BAD}"/><path d="M${x - 7} ${y - 7} l14 14 M${x + 7} ${y - 7} l-14 14" stroke="#fff" stroke-width="4.5" stroke-linecap="round"/></g>`;
const cross = (x, y, s = 26) => `<path d="M${x - s} ${y - s} L${x + s} ${y + s} M${x + s} ${y - s} L${x - s} ${y + s}" stroke="${BAD}" stroke-width="7" stroke-linecap="round" opacity=".9"/>`;
function timer(x, y, label) {
  return C(x, y, 30, '#fff') + `<line x1="${x}" y1="${y}" x2="${x}" y2="${y - 20}" stroke="${INK}" stroke-width="3"/><line x1="${x}" y1="${y}" x2="${x + 14}" y2="${y + 6}" stroke="${INK}" stroke-width="3"/>` + R(x - 6, y - 40, 12, 8, INK, 2) + (label ? T(x, y + 56, label, 20) : '');
}
// side-view head facing right; mouth around (hx+34, hy+20)
function head(hx, hy, mouth = 'closed', opts = {}) {
  const tilt = opts.tilt || 0;
  const m = mouth === 'open' ? `<ellipse cx="${hx + 33}" cy="${hy + 21}" rx="5" ry="6" fill="#7f1d1d" stroke="${INK}" stroke-width="2.5"/>`
    : mouth === 'o' ? `<circle cx="${hx + 35}" cy="${hy + 21}" r="4" fill="#7f1d1d" stroke="${INK}" stroke-width="2.5"/>`
      : `<path d="M${hx + 28} ${hy + 21} q5 2 9 0" fill="none" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>`;
  const eye = opts.eyeUp ? `<circle cx="${hx + 19}" cy="${hy - 14}" r="3.5" fill="${INK}"/>` : opts.eyeClosed ? `<path d="M${hx + 14} ${hy - 9} q5 3 10 0" fill="none" stroke="${INK}" stroke-width="3" stroke-linecap="round"/>` : `<circle cx="${hx + 19}" cy="${hy - 9}" r="3.5" fill="${INK}"/>`;
  const body = `<path d="M${hx - 34} ${hy + 108} C${hx - 30} ${hy + 70} ${hx - 10} ${hy + 62} ${hx - 6} ${hy + 44} L${hx + 14} ${hy + 44} C${hx + 18} ${hy + 62} ${hx + 40} ${hy + 72} ${hx + 46} ${hy + 108} Z" fill="#93c5fd" stroke="${INK}" stroke-width="3"/>`;
  const face = `<path d="M${hx - 30} ${hy - 6} C${hx - 32} ${hy - 44} ${hx + 6} ${hy - 54} ${hx + 26} ${hy - 38} C${hx + 34} ${hy - 30} ${hx + 34} ${hy - 18} ${hx + 36} ${hy - 6} L${hx + 47} ${hy + 6} L${hx + 37} ${hy + 10} L${hx + 39} ${hy + 30} C${hx + 36} ${hy + 40} ${hx + 24} ${hy + 44} ${hx + 12} ${hy + 46} L${hx - 8} ${hy + 46} C${hx - 24} ${hy + 34} ${hx - 30} ${hy + 18} ${hx - 30} ${hy - 6} Z" fill="${SKIN}" stroke="${INK}" stroke-width="3"/>`;
  const hair = `<path d="M${hx - 31} ${hy - 4} C${hx - 36} ${hy - 50} ${hx + 10} ${hy - 62} ${hx + 30} ${hy - 34} C${hx + 14} ${hy - 40} ${hx} ${hy - 34} ${hx - 10} ${hy - 22} C${hx - 16} ${hy - 14} ${hx - 22} ${hy - 6} ${hx - 31} ${hy - 4} Z" fill="#374151" stroke="${INK}" stroke-width="3"/>`;
  const ear = `<ellipse cx="${hx - 8}" cy="${hy + 2}" rx="7" ry="11" fill="${SKIN2}" stroke="${INK}" stroke-width="2.5"/>`;
  return `<g transform="rotate(${tilt} ${hx} ${hy + 40})">${body}${face}${hair}${ear}${eye}${m}</g>`;
}
