  respimat: (o = {}) => `${R(0, -10, 26, 20, '#9ca3af', 4)}${R(20, -40, 40, 150, '#d1d5db', 12)}${R(20, 80, 40, 50, 'rgba(186,230,253,.9)', 10)}<line x1="24" y1="95" x2="56" y2="95" stroke="${INK}" stroke-width="2"/><line x1="24" y1="108" x2="56" y2="108" stroke="${INK}" stroke-width="2"/>${R(58, 0, 10, 26, '#6b7280', 3)}${o.capOpen ? P('M20 -38 C-6 -50 -16 -20 -4 -12', o.accent || '#14b8a6', 9) : R(14, -62, 52, 30, o.accent || '#14b8a6', 14)}<rect x="30" y="40" width="20" height="10" fill="#fff" stroke="${INK}" stroke-width="2"/>`,
