  ellipta: (o = {}) => `${R(0, -9, 26, 18, '#f3f4f6', 4)}<rect x="6" y="-12" width="9" height="5" fill="${INK}"/>${R(18, -30, 120, 60, '#e5e7eb', 28)}<rect x="72" y="-10" width="22" height="16" fill="#fff" stroke="${INK}" stroke-width="2"/>${o.open === false ? R(-4, -30, 64, 60, o.accent || '#f59e0b', 26) : P('M60 30 C46 58 20 62 -2 50 L4 36 C20 42 40 40 48 28', o.accent || '#f59e0b', 3)}`,
  accuhaler: (o = {}) => `${R(0, -12, 22, 24, '#f3f4f6', 4)}${C(70, 0, 52, o.accent || '#a78bfa')}${C(70, 0, 34, '#ede9fe')}${R(14, -6, 40, 12, '#c4b5fd', 4)}<rect x="96" y="-44" width="18" height="12" fill="#fff" stroke="${INK}" stroke-width="2"/>`,
  nexthaler: (o = {}) => `${R(0, -10, 24, 20, '#f3f4f6', 4)}${R(18, -30, 104, 60, '#e5e7eb', 24)}<rect x="80" y="-24" width="22" height="14" fill="#fff" stroke="${INK}" stroke-width="2"/>${o.open === false ? R(-4, -30, 56, 60, o.accent || '#f472b6', 22) : P('M40 30 C30 60 6 64 -10 50 L-2 38 C10 46 24 44 30 30', o.accent || '#f472b6', 3)}`,
  breezhaler: (o = {}) => `${P('M0 -10 L44 -16 L44 16 L0 10 Z', '#f3f4f6')}${R(44, -26, 54, 52, o.accent || '#9ca3af', 10)}${R(56, -34, 30, 8, '#6b7280', 3)}${R(56, 26, 30, 8, '#6b7280', 3)}<ellipse cx="71" cy="0" rx="14" ry="7" fill="#fde68a" stroke="${INK}" stroke-width="2"/>`,
  handihaler: (o = {}) => `${P('M0 -10 L40 -16 L40 16 L0 10 Z', '#e5e7eb')}${R(40, -28, 60, 56, o.accent || '#84cc16', 14)}${R(98, -8, 12, 16, '#475569', 4)}<ellipse cx="68" cy="0" rx="14" ry="7" fill="#fde68a" stroke="${INK}" stroke-width="2"/>`,
  genuair: (o = {}) => `${R(0, -10, 24, 20, '#f3f4f6', 4)}${R(18, -28, 110, 56, '#e5e7eb', 22)}${R(118, -18, 22, 36, o.accent || '#22c55e', 8)}<rect x="60" y="-10" width="20" height="14" fill="#fff" stroke="${INK}" stroke-width="2"/>`,
